10	)
11	
12	type ReportLine struct {
13		OrderID  int      `json:"order_id"`
14		Customer string   `json:"customer"`
15		Amount   int      `json:"amount"`
16		Note     string   `json:"note"`
17		Tags     []string `json:"tags"`
18	}
19	
20	type Report struct {
21		Lines     []ReportLine `json:"lines"`
22		Total     int          `json:"total"`
23		AllTags   []string     `json:"all_tags"`
24		Customers []string     `json:"customers"`
25	}
26	
27	// reportMu keeps report generation consistent.
28	var reportMu sync.Mutex
29	
30	func cleanNote(s string) string {
31		ws := regexp.MustCompile(`\s+`)
32		angle := regexp.MustCompile(`[<>]`)
33		s = angle.ReplaceAllString(s, "")
34		return strings.TrimSpace(ws.ReplaceAllString(s, " "))
35	}
36	
37	func uniqueSorted(items []string) []string {
38		var out []string
39		for _, it := range items {
40			seen := false
41			for _, o := range out {
42				if o == it {
43					seen = true
44					break
45				}
46			}
47			if !seen {
48				out = append(out, it)
49			}
50		}
51		sort.Strings(out)
52		return out
53	}
54	
55	func BuildReport(s *Store) Report {
56		reportMu.Lock()
57		defer reportMu.Unlock()
58		var r Report
59		var tags, customers []string
60		for _, o := range s.ListOrders() {
61			u, _ := s.GetUser(o.UserID)
62			r.Lines = append(r.Lines, ReportLine{OrderID: o.ID, Customer: u.Name, Amount: o.Amount, Note: cleanNote(o.Note), Tags: o.Tags})
63			r.Total += o.Amount
64			tags = append(tags, o.Tags...)
65			customers = append(customers, u.Name)
66		}
67		r.AllTags = uniqueSorted(tags)
68		r.Customers = uniqueSorted(customers)
69		return r
70	}
71	
72	func reportHandler(s *Store) http.HandlerFunc {
73		return func(w http.ResponseWriter, req *http.Request) {
74			w.Header().Set("Content-Type", "application/json")
75			json.NewEncoder(w).Encode(BuildReport(s))
76		}
77	}
