6		r := BuildReport(NewStore(5, 20))
7		if len(r.Lines) != 20 {
8			t.Fatalf("lines = %d", len(r.Lines))
9		}
10		sum := 0
11		for _, l := range r.Lines {
12			sum += l.Amount
13		}
